text:
& .config-title {
  color: light-dark(var(--color-primary-default), #feffff);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  padding-block: var(--hub-config-option-padding-block) 2px;
  padding-inline: var(--hub-config-option-padding-inline);
  font-weight: bold;

  & .config-title-text {
    flex: 1;
    line-height: 1;
  }

  & input[type="radio"] {
    appearance: none;
    background-color: transparent;
    margin-inline-end: 8px;
    inline-size: 15px;
    block-size: 15px;
    border: 1px solid var(--color-surface-border-intense);
    border-radius: 50%;
    display: grid;
    place-content: center;

    &::before {
      content: "";
      inline-size: 5px;
      block-size: 5px;
      border-radius: 50%;
      transform: scale(0);
      box-shadow: inset 1em 1em var(--color-surface-base);
    }

    &:checked::before {
      transform: scale(1);
    }
  }
}

& .config-text {
  color: var(--color-text-base);
  font-weight: 400;
  padding-block: 2px var(--hub-config-option-padding-block);
  padding-inline: var(--hub-config-option-padding-inline);
  font-size: 1.1rem;
}

&.selected {
  border-color: var(--color-primary-default);

  & .config-title {
    background-color: var(--color-primary-default);
    color: var(--color-surface-base);
    padding-block: var(--hub-config-option-padding-block);
  }

  & .config-text {
    color: light-dark(#15427c, var(--color-text-base));
    background-color: var(--color-surface-base);
    padding-block: var(--hub-config-option-padding-block);
  }
